const app=document.getElementById('app');
let me=null,tracks=[],state={};
const icons={dashboard:'◫',interns:'◎',admins:'♙',tasks:'✓',submissions:'⇧',meetings:'◷',notes:'✦',complaints:'!',certificates:'◇',activity:'⌁',leads:'◉',settings:'⚙',resources:'▣',announcements:'◆',notifications:'●',profile:'○',learning:'▶'};

async function api(url,opts={}){
  const o={...opts,headers:{...(opts.headers||{})}};
  if(o.body && !(o.body instanceof FormData) && typeof o.body!=='string') o.body=JSON.stringify(o.body);
  if(o.body && !(o.body instanceof FormData) && !o.headers['Content-Type']) o.headers['Content-Type']='application/json';
  const r=await fetch(url,o);
  const ct=r.headers.get('content-type')||'';
  const d=ct.includes('application/json')?await r.json():await r.text();
  if(!r.ok) throw new Error(d?.detail||d||`Request failed ${r.status}`);
  return d;
}
function esc(s=''){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmt(x){if(!x)return '—';try{return new Date(x).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}catch{return x}}
function dateOnly(x){if(!x)return '—';try{return new Date(x).toLocaleDateString([],{dateStyle:'medium'})}catch{return x}}
function initials(n=''){return n.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),3000)}
function err(e){console.error(e);toast(e.message||'Something went wrong')}
function badge(v){const s=String(v||'').toLowerCase();let c=s.includes('complete')||s==='active'||s==='valid'||s==='present'?'b-green':s.includes('late')||s.includes('high')||s.includes('reject')||s.includes('terminated')?'b-red':s.includes('medium')||s.includes('pending')||s.includes('review')?'b-orange':s.includes('boot')?'b-purple':'b-blue';return `<span class="badge ${c}">${esc(v)}</span>`}
function btn(label,fn,cls='btn-soft'){return `<button class="btn ${cls}" onclick="${fn}">${label}</button>`}
function modal(title,html){const d=document.createElement('div');d.className='modal';d.innerHTML=`<div class="modal-card"><div class="modal-head"><h2 style="margin:0">${title}</h2><button class="close">×</button></div>${html}</div>`;d.querySelector('.close').onclick=()=>d.remove();d.onclick=e=>{if(e.target===d)d.remove()};document.body.append(d);return d}
function hero(title,desc,eyebrow='HVIA MANAGEMENT SYSTEM'){return `<div class="hero cinematic-hero"><div class="hero-copy"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p><div class="hero-signature"><span>LEARN</span><i></i><span>BUILD</span><i></i><span>GROW</span><i></i><span>BELONG</span></div></div><div class="hero-portal"><div class="portal-glow"></div><div class="portal-copy">PEOPLE<br>DATA<br>IDEAS<br><b>A BRIGHTER<br>TOMORROW</b></div></div></div>`}
function kpi(label,value,sub=''){return `<div class="card kpi"><div class="label">${label}</div><div class="value">${value}</div>${sub?`<div class="sub">${sub}</div>`:''}</div>`}
function fileSize(n){if(!n)return '0 B';if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`}

async function boot(){
  try{me=await api('/api/auth/me');tracks=await api('/api/tracks');if(me.role==='intern'&&!me.profile_completed)return onboarding();shell();}
  catch{gateway()}
}

function gateway(){
  app.innerHTML=`<section class="gateway"><div class="gateway-inner"><img class="brand-logo" src="/assets/logo.svg"><div style="margin-top:80px"><div class="eyebrow">NEW BEGINNINGS</div><h1>BUILD TOMORROW<br>WITH <span class="accent">HVIA</span></h1><p>A cinematic control center for learning, mentoring, operations and measurable progress — powered by one connected HVIA platform.</p><div class="gateway-cards"><div class="choice"><div class="icon">◈</div><h3>Employee / Intern Portal</h3><p>Super Admin, Admin / Mentor and Intern access. Tasks, reviews, meetings, learning and operations.</p><button class="btn btn-primary" onclick="loginView()">Enter Platform →</button></div><div class="choice"><div class="icon">◎</div><h3>Explore HVIA</h3><p>Browse products and demos, discover HVIA solutions and send a business request directly through WhatsApp.</p><button class="btn btn-outline" onclick="publicView()">Browse Solutions →</button></div></div></div></div></section>`;
}

