  const demos=await api('/api/public/demos').catch(()=>[]);
  app.innerHTML=`<div class="public"><nav class="public-nav"><img src="/assets/logo.svg"><div class="public-links"><a href="#demos">Demos</a><a href="#contact">Contact</a><button class="btn btn-outline" onclick="gateway()">Portal</button></div></nav><section class="public-hero"><div><div class="eyebrow">DATA · PEOPLE · IMPACT</div><h1>REAL SOLUTIONS.<br><span class="accent">BRIGHTER TOMORROWS.</span></h1><p>HVIA builds data-driven products and management systems that turn operational data into visibility, decisions and measurable impact.</p><div class="group" style="margin-top:24px"><a class="btn btn-primary" href="#demos">Explore Demos →</a><a class="btn btn-outline" href="#contact">Request a Demo</a></div></div></section><section class="public-section" id="demos"><div class="section-head"><div><div class="eyebrow">HVIA PRODUCTS</div><h2>Explore Our Demos</h2></div><p class="muted">Built for real business operations.</p></div><div class="demo-grid">${demos.map(x=>`<div class="demo-card"><span class="badge b-blue">${esc(x.category)}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="group" style="position:absolute;bottom:20px"><button class="btn btn-soft" onclick="requestDemo('${esc(x.name)}')">Request Demo</button>${x.demo_url&&x.demo_url!=='#'?`<a class="btn btn-outline" href="${esc(x.demo_url)}" target="_blank">Open</a>`:''}</div></div>`).join('')}</div></section><section class="public-section" id="contact"><div class="contact-panel"><div><div class="eyebrow">LET'S BUILD TOGETHER</div><h2>Request a Demo</h2><p>Send your details. The request is saved in HVIA Control Center and you can continue directly on WhatsApp.</p><p><b>WhatsApp:</b> 012 2297 0033</p></div><form id="contactForm" class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Company</label><input name="company"></div><div class="field span2"><label>Interest</label><input name="interest" id="interest"></div><div class="field span2"><label>Message</label><textarea name="message" rows="4"></textarea></div><button class="btn btn-primary span2">Send Request on WhatsApp →</button></form></div></section><footer class="public-footer"><span>HVIA · Data & AI Solutions</span><span>People · Data · A Brighter Tomorrow</span></footer></div>`;
  document.getElementById('contactForm').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const r=await api('/api/public/contact',{method:'POST',body:data});toast('Request saved');window.open(r.whatsapp_url,'_blank')}catch(ex){err(ex)}};
