function requestDemo(name){document.getElementById('interest')?.setAttribute('value',name);document.getElementById('contact')?.scrollIntoView({behavior:'smooth'});setTimeout(()=>{const i=document.getElementById('interest');if(i)i.value=name},250)}

function loginView(){
  app.innerHTML=`<div class="login"><section class="login-visual"><div class="login-copy"><div class="eyebrow">LEARN · BUILD · GROW · BELONG</div><h1>WELCOME TO<br><span class="accent">HVIA</span></h1><p>Secure access to the HVIA internship, mentoring and learning management system.</p></div></section><section class="login-panel"><form class="login-card" id="loginForm"><img src="/assets/logo.svg"><h2>Welcome Back</h2><p>Sign in with the account provided by HVIA.</p><div class="field"><label>Email</label><input name="email" type="email" autocomplete="username" required placeholder="yourname@hvia.ai"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn btn-primary btn-block">Sign In →</button><div class="group" style="justify-content:space-between;margin-top:16px"><button type="button" class="btn btn-outline" onclick="gateway()">← Back</button><span class="small">No public sign up</span></div></form></section></div>`;
  document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();try{me=await api('/api/auth/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});tracks=await api('/api/tracks');if(me.role==='intern'&&!me.profile_completed)onboarding();else shell()}catch(ex){err(ex)}};
}

function onboarding(){
  let selected=me.track?.id||null;
  app.innerHTML=`<div class="onboard"><img class="onboard-logo" src="/assets/logo.svg"><div class="steps"><div class="step active">1 · Complete Profile</div><div class="step active">2 · Choose Track</div><div class="step">3 · Start Journey</div></div><form class="onboard-card" id="onboardForm"><div class="eyebrow">FIRST LOGIN</div><h1>Complete Your HVIA Profile</h1><p class="muted">Your login account already exists. Add your professional information and choose one learning path.</p><div class="form-grid" style="margin-top:22px"><div class="field"><label>Full Name</label><input value="${esc(me.full_name)}" disabled></div><div class="field"><label>HVIA Email</label><input value="${esc(me.email)}" disabled></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Age</label><input name="age" type="number" min="14" max="80"></div><div class="field"><label>Personal Email</label><input name="personal_email" type="email" value="${esc(me.personal_email||'')}"></div><div class="field"><label>LinkedIn</label><input name="linkedin_url" placeholder="https://linkedin.com/in/..."></div><div class="field"><label>University</label><input name="university"></div><div class="field"><label>Faculty</label><input name="faculty"></div><div class="field"><label>Graduation Year</label><input name="graduation_year" type="number"></div><div class="field span2"><label>About You</label><textarea name="bio" rows="3"></textarea></div></div><h3>Choose Your Track</h3><div class="track-choice">${tracks.map(t=>`<div class="track-option" data-id="${t.id}"><b>${esc(t.name)}</b><div class="small" style="margin-top:5px">${esc(t.description||'')}</div></div>`).join('')}</div><input type="hidden" name="track_id" id="track_id"><div class="group" style="margin-top:22px;justify-content:flex-end"><button type="button" class="btn btn-outline" onclick="logout()">Logout</button><button class="btn btn-primary">Save & Enter Dashboard →</button></div></form></div>`;
  document.querySelectorAll('.track-option').forEach(x=>x.onclick=()=>{document.querySelectorAll('.track-option').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');selected=Number(x.dataset.id);document.getElementById('track_id').value=selected});
  document.getElementById('onboardForm').onsubmit=async e=>{e.preventDefault();if(!selected)return toast('Choose a track');const f=Object.fromEntries(new FormData(e.target));['age','graduation_year','track_id'].forEach(k=>f[k]=f[k]?Number(f[k]):null);try{me=await api('/api/profile/complete',{method:'POST',body:f});shell()}catch(ex){err(ex)}};
}

function navItems(){
  if(me.role==='super_admin')return [['CONTROL','dashboard','Control Center'],['PEOPLE','interns','Interns'],['','admins','Admins & Mentors'],['OPERATIONS','tasks','Tasks'],['','submissions','Submissions'],['','meetings','Meetings & Attendance'],['','notes','Admin Notes'],['','complaints','Complaints'],['LEARNING','resources','Resources'],['','announcements','Announcements'],['','activity','Audit Log'],['BUSINESS','leads','Demo Requests'],['SYSTEM','settings','Settings'],['ACCOUNT','profile','My Profile']];
  if(me.role==='admin')return [['WORKSPACE','dashboard','Dashboard'],['MENTORING','interns','My Interns'],['','tasks','Tasks'],['','submissions','Submissions'],['','meetings','Meetings & Attendance'],['COMMUNICATION','notes','Super Admin Notes'],['','announcements','Announcements'],['LEARNING','resources','Resources'],['ACCOUNT','profile','My Profile']];
  return [['MY JOURNEY','dashboard','Dashboard'],['','tasks','My Tasks'],['','meetings','Meetings'],['','resources','My Learning'],['COMMUNICATION','announcements','Announcements'],['','notifications','Notifications'],['','complaints','Complaints'],['ACCOUNT','profile','My Profile']];
}
function shell(){
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="side-logo"><img src="/assets/logo.svg"><div class="role-pill">${me.role.replace('_',' ')}</div></div><div class="nav" id="nav">${navItems().map(([sec,id,label])=>`${sec?`<div class="section">${sec}</div>`:''}<button data-view="${id}"><span class="nav-icon">${icons[id]||'•'}</span>${label}</button>`).join('')}</div><div class="sidebar-foot"><b>HVIA CONTROL CENTER</b><br><span class="neon-ver">DUAL PORTAL · V4</span><br>Learn · Build · Grow · Belong</div></aside><main class="main"><header class="topbar"><div class="top-brand"><span class="pulse-dot"></span><b>HVIA</b><span>CONTROL CENTER</span></div><input class="search" id="globalSearch" placeholder="Search ${me.role==='super_admin'?'interns, tasks, meetings...':'your workspace...'}"><div class="top-actions"><button class="notify-btn" onclick="openNotifications()">◉<span class="notify-count" id="notifyCount">0</span></button><div class="user-chip"><div class="avatar" id="topAvatar">${me.profile_picture?`<img src="${me.profile_picture}?t=${Date.now()}">`:initials(me.full_name)}</div><div><b>${esc(me.full_name)}</b><div class="small">${me.role.replace('_',' ')}</div></div></div><div class="edition-badge">V3 FAST</div><button class="btn btn-outline" onclick="logout()">Logout</button></div></header><div class="content" id="content"></div></main></div>`;
  document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.view,b));
  if(me.role==='super_admin')document.getElementById('globalSearch').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim())globalSearch(e.target.value.trim())};
  refreshNotifications();go('dashboard',document.querySelector('#nav button[data-view="dashboard"]'));
}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}me=null;gateway()}
function go(view,el){document.querySelectorAll('#nav button').forEach(x=>x.classList.remove('active'));(el||document.querySelector(`#nav button[data-view="${view}"]`))?.classList.add('active');const c=document.getElementById('content');c.innerHTML='<div class="card">Loading...</div>';const fn={dashboard:viewDashboard,interns:viewInterns,admins:viewAdmins,tasks:viewTasks,submissions:viewSubmissions,meetings:viewMeetings,notes:viewNotes,complaints:viewComplaints,activity:viewActivity,leads:viewLeads,settings:viewSettings,resources:viewResources,announcements:viewAnnouncements,notifications:viewNotifications,profile:viewProfile}[view];fn?fn(c).catch(err):c.innerHTML='Unknown view'}

async function refreshNotifications(){try{const n=await api('/api/notifications');document.getElementById('notifyCount').textContent=n.filter(x=>!x.is_read).length}catch{}}
async function openNotifications(){const n=await api('/api/notifications');const d=modal('Notifications',n.length?n.map(x=>`<div class="announcement"><div class="toolbar"><b>${esc(x.title)}</b>${x.is_read?badge('Read'):badge('New')}</div><div>${esc(x.message)}</div><div class="small" style="margin-top:8px">${fmt(x.created_at)}</div>${!x.is_read?`<button class="btn btn-soft" style="margin-top:8px" onclick="markRead(${x.id},this)">Mark read</button>`:''}</div>`).join(''):'<div class="empty">No notifications.</div>');return d}
async function markRead(id,btn){await api(`/api/notifications/${id}/read`,{method:'PATCH'});btn.remove();refreshNotifications()}

async function viewDashboard(c){
  const d=await api('/api/dashboard');
  if(me.role==='super_admin'){
    const k=d.kpis;c.innerHTML=hero('HVIA Control Center','A live operational view of interns, mentors, tasks, reviews, meetings, complaints and system activity.','SUPER ADMIN')+`<div class="grid kpis">${kpi('Active Interns',k.interns)}${kpi('Admins / Mentors',k.admins)}${kpi('Online Now',k.online_users)}${kpi('Logins Today',k.logins_today)}${kpi('Pending Reviews',k.pending_reviews)}${kpi('Submissions Today',k.submissions_today)}${kpi('Late · 7 Days',k.late_week)}${kpi('Meetings Today',k.meetings_today)}${kpi('Open Complaints',k.open_complaints)}${kpi('At-Risk Interns',k.at_risk)}</div><div class="grid two"><div class="card"><h3>Live Activity Feed</h3>${d.events.slice(0,12).map(x=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(x.actor)}</b> · ${esc(x.action.replaceAll('_',' '))}<div class="small">${fmt(x.created_at)}</div></div></div>`).join('')}</div><div><div class="card"><h3>Enrollment by Track</h3>${d.tracks.map(t=>`<div class="track-row"><b>${esc(t.name)}</b><span>${t.count}</span><div class="bar"><i style="width:${Math.max(6,t.count/Math.max(k.interns,1)*100)}%"></i></div></div>`).join('')}</div><div class="card" style="margin-top:14px"><h3>At-Risk Rules</h3>${d.at_risk.length?d.at_risk.slice(0,6).map(x=>`<div class="announcement"><b>${esc(x.name)}</b><div class="small">${esc(x.reasons.join(' · '))}</div></div>`).join(''):'<div class="empty">No interns currently flagged by the deterministic risk rules.</div>'}</div></div></div>`;
  }else if(me.role==='admin'){
    const k=d.kpis;c.innerHTML=hero('Mentor Workspace','Manage your assigned interns, create tasks, review submissions and schedule follow-ups.','ADMIN / MENTOR')+`<div class="grid kpis">${kpi('Assigned Interns',k.assigned_interns)}${kpi('Pending Reviews',k.pending_reviews)}${kpi('Reviews Completed',k.reviews_done)}${kpi('Tasks Created',k.tasks_created)}${kpi('Meetings Created',k.meetings)}</div><div class="card" style="margin-top:15px"><div class="toolbar"><h3>Recent Submissions</h3><button class="btn btn-primary" onclick="go('submissions')">Review Queue →</button></div>${submissionTable(d.recent_submissions,true)}</div>`;
  }else{
    const k=d.kpis;c.innerHTML=hero(`Welcome back, ${esc(me.full_name.split(' ')[0])}`,'Track your tasks, meetings, learning, work hours and certificate eligibility.','MY HVIA JOURNEY')+`<div class="grid kpis">${kpi('Task Completion',`${k.completion_percent}%`,`${k.completed}/${k.total} completed`)}${kpi('Average Score',k.avg_score)}${kpi('Work Hours',k.hours)}${kpi('Attendance',`${k.attendance}%`)}${kpi('Unread Alerts',k.notifications)}</div><div class="grid two"><div class="card"><h3>Your Track</h3><h2>${esc(d.track?.name||'Pending')}</h2><p class="muted">${d.track?.program_type==='bootcamp'?'Bootcamp learning path':'Internship track'}</p><div class="group"><button class="btn btn-primary" onclick="go('tasks')">Open My Tasks</button><button class="btn btn-outline" onclick="go('meetings')">Meetings</button></div></div><div class="card"><h3>Certificate Eligibility</h3><div class="group"><div class="metric-ring" style="--p:${Math.min(100,d.eligibility.task_completion)}"><span>${d.eligibility.task_completion}%</span></div><div><p>Task completion requirement: <b>${d.eligibility.min_task}%</b></p><p>Attendance requirement: <b>${d.eligibility.min_attendance}%</b></p>${d.eligibility.eligible?badge('Eligible'):badge('In Progress')}</div></div></div></div>`;
  }
}

async function viewInterns(c){
  const rows=await api('/api/interns');state.interns=rows;c.innerHTML=hero(me.role==='super_admin'?'Intern Management':'My Interns',me.role==='super_admin'?'Add, edit, reassign, monitor and report every intern.':'Your mentoring scope and individual intern performance.','PEOPLE & PERFORMANCE')+`<div class="card" style="margin-top:15px"><div class="toolbar"><div class="group"><input class="mini-input" id="internFilter" placeholder="Search name, email or ID"><select class="mini-input" id="trackFilter"><option value="">All Tracks</option>${tracks.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div>${me.role==='super_admin'?'<button class="btn btn-primary" onclick="addIntern()">+ Add Intern</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Intern</th><th>Track</th><th>Status</th><th>Tasks</th><th>Score</th><th>Hours</th><th>Attendance</th><th>Actions</th></tr></thead><tbody id="internRows"></tbody></table></div></div>`;renderInternRows(rows);document.getElementById('internFilter').oninput=filterInterns;document.getElementById('trackFilter').onchange=filterInterns;
}
function renderInternRows(rows){const tb=document.getElementById('internRows');tb.innerHTML=rows.map(x=>`<tr><td>${esc(x.internal_id)}</td><td><b>${esc(x.full_name)}</b><div class="small">${esc(x.email)}</div></td><td>${esc(x.track?.name||'Pending')}</td><td>${badge(x.status)}</td><td>${x.report.tasks.completed}/${x.report.tasks.total}</td><td>${x.report.tasks.avg_score}</td><td>${x.report.hours}</td><td>${x.report.attendance.percent}%</td><td><div class="actions"><button class="btn btn-soft" onclick="internDetail(${x.id})">Profile</button>${me.role==='super_admin'?`<button class="btn btn-outline" onclick="changeTrack(${x.id})">Track</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="9">No interns.</td></tr>'}
function filterInterns(){const q=document.getElementById('internFilter').value.toLowerCase(),t=document.getElementById('trackFilter').value;renderInternRows(state.interns.filter(x=>(!q||`${x.full_name} ${x.email} ${x.internal_id}`.toLowerCase().includes(q))&&(!t||x.track?.name===t)))}
function addIntern(){const d=modal('Add Intern',`<form><div class="field"><label>Full Name</label><input name="full_name" required></div><div class="field"><label>HVIA Login Email</label><input name="email" type="email" required></div><div class="field"><label>Initial Password</label><input name="password" required></div><div class="field"><label>Personal Email</label><input name="personal_email" type="email"></div><button class="btn btn-primary">Create Account</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/interns',{method:'POST',body:Object.fromEntries(new FormData(e.target))});d.remove();toast('Intern created');go('interns')}catch(ex){err(ex)}}}
function changeTrack(id){const person=state.interns.find(x=>x.id===id);const d=modal(`Change Track · ${esc(person.full_name)}`,`<div class="field"><label>Track</label><select id="newTrack">${tracks.map(t=>`<option value="${t.id}" ${person.track?.id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><button class="btn btn-primary" id="saveTrack">Update Track</button>`);d.querySelector('#saveTrack').onclick=async()=>{try{await api(`/api/interns/${id}/track`,{method:'PATCH',body:{track_id:Number(d.querySelector('#newTrack').value)}});d.remove();toast('Track updated');go('interns')}catch(ex){err(ex)}}}
function warningModal(id){const d=modal('Add Warning',`<form><div class="field"><label>Type</label><select name="warning_type"><option>Attendance</option><option>Late Submission</option><option>Performance</option><option>Behavior</option><option>Other</option></select></div><div class="field"><label>Severity</label><select name="severity"><option>Minor</option><option>Moderate</option><option>Major</option></select></div><div class="field"><label>Note</label><textarea name="note" required></textarea></div><button class="btn btn-primary">Save Warning</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.user_id=id;try{await api('/api/warnings',{method:'POST',body:p});d.remove();toast('Warning saved')}catch(ex){err(ex)}}}

async function viewAdmins(c){const rows=await api('/api/admins');state.admins=rows;if(!state.interns)state.interns=await api('/api/interns');c.innerHTML=hero('Admins & Mentors','Super Admin control over monitor access, activity and assigned interns.','ROLE CONTROL')+`<div class="card" style="margin-top:15px"><div class="toolbar"><h3>Mentor Team</h3><button class="btn btn-primary" onclick="addAdmin()">+ Add Admin</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Admin</th><th>Last Login</th><th>Interns</th><th>Tasks</th><th>Reviews</th><th>Meetings</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${esc(a.full_name)}</b><div class="small">${esc(a.email)}</div></td><td>${fmt(a.last_login_at)}</td><td>${a.assigned_interns}</td><td>${a.tasks_created}</td><td>${a.reviews}</td><td>${a.meetings_created}</td><td><div class="actions"><button class="btn btn-outline" onclick="assignMentor(${a.id})">Assign Interns</button><button class="btn btn-outline" onclick="noteAdmin(${a.id})">Note</button><button class="btn btn-danger" onclick="archiveAdmin(${a.id})">Archive</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function addAdmin(){const d=modal('Add Admin / Mentor',`<form><div class="field"><label>Name</label><input name="full_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" required></div><button class="btn btn-primary">Create Admin</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admins',{method:'POST',body:Object.fromEntries(new FormData(e.target))});d.remove();toast('Admin created');go('admins')}catch(ex){err(ex)}}}
function assignMentor(id){const a=state.admins.find(x=>x.id===id);const d=modal(`Assign Interns · ${esc(a.full_name)}`,`<div style="max-height:420px;overflow:auto">${state.interns.map(i=>`<label class="file-row"><span><b>${esc(i.full_name)}</b><div class="small">${esc(i.track?.name||'Pending')}</div></span><input type="checkbox" value="${i.id}"></label>`).join('')}</div><button class="btn btn-primary" style="margin-top:14px" id="saveScope">Save Mentor Scope</button>`);d.querySelector('#saveScope').onclick=async()=>{const ids=[...d.querySelectorAll('input:checked')].map(x=>Number(x.value));try{await api(`/api/admins/${id}/assign-interns`,{method:'POST',body:{intern_ids:ids}});d.remove();toast('Mentor scope updated');go('admins')}catch(ex){err(ex)}}}
function noteAdmin(id){const d=modal('Send Note to Admin',`<form><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div class="field"><label>Note</label><textarea name="content" rows="5" required></textarea></div><button class="btn btn-primary">Send Notification</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.admin_id=id;try{await api('/api/admin-notes',{method:'POST',body:p});d.remove();toast('Note sent')}catch(ex){err(ex)}}}
async function archiveAdmin(id){if(!confirm('Archive this admin account?'))return;try{await api(`/api/admins/${id}`,{method:'DELETE'});toast('Admin archived');go('admins')}catch(ex){err(ex)}}

async function viewTasks(c){const rows=await api('/api/tasks');state.tasks=rows;c.innerHTML=hero(me.role==='intern'?'My Tasks':'Task Management',me.role==='intern'?'Move work to In Progress, track time and submit any required files.':'Create and assign tasks with unrestricted task attachments: notebook, PDF, Word, ZIP, source code or any file type.','TASKS & DELIVERY')+`${me.role!=='intern'?`<div class="card" style="margin-top:15px"><div class="toolbar"><div><b>${rows.length} Tasks</b><div class="small">Task files can be any format.</div></div><button class="btn btn-primary" onclick="createTask()">+ Create Task & Upload Files</button></div></div>`:''}<div style="margin-top:15px">${me.role==='intern'?taskBoard(rows):taskManagementTable(rows)}</div>`}
function taskBoard(rows){const statuses=['To Do','In Progress','Submitted','Under Review','Completed'];return `<div class="task-board">${statuses.map(s=>`<div class="lane"><h4>${s}<span>${rows.filter(t=>(t.progress||'To Do')===s).length}</span></h4>${rows.filter(t=>(t.progress||'To Do')===s).map(t=>taskCard(t)).join('')||'<div class="small">No tasks</div>'}</div>`).join('')}</div>`}
function taskCard(t){const score=t.submission?.score!=null?`<div style="margin-top:8px">${badge(`Score ${t.submission.score}/${t.max_score}`)}</div>`:'';return `<div class="task"><strong>${esc(t.title)}</strong><div class="group">${badge(t.priority)}${t.submission?.is_late?badge('Late'):''}</div><div class="small" style="margin-top:7px">Due ${fmt(t.deadline)}</div>${score}<div class="meta"><span>${t.attachments.length} task files</span><button class="btn btn-soft" onclick="taskDetail(${t.id})">Open</button></div></div>`}
function taskTargetLabel(t){
  if(t.target_type==='all')return `All Interns (${t.assigned_count||0})`;
  if(t.target_type==='track')return `${esc(t.target_track_name||'Track')} (${t.assigned_count||0})`;
  return `Selected Students (${t.assigned_count||0})`;
}
function taskManagementTable(rows){return `<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Assigned To</th><th>Deadline</th><th>Priority</th><th>Files</th><th>Created</th><th>Actions</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.title)}</b><div class="small">${esc(t.description).slice(0,90)}</div></td><td><b>${taskTargetLabel(t)}</b><div class="small">${(t.assigned_students||[]).slice(0,3).map(x=>esc(x.name)).join(' · ')}${(t.assigned_count||0)>3?' · +'+((t.assigned_count||0)-3):''}</div></td><td>${fmt(t.deadline)}</td><td>${badge(t.priority)}</td><td>${t.attachments.length}</td><td>${dateOnly(t.created_at)}</td><td><div class="actions"><button class="btn btn-soft" onclick="taskDetail(${t.id})">View</button><button class="btn btn-outline" onclick="uploadTaskFiles(${t.id})">+ Files</button></div></td></tr>`).join('')}</tbody></table></div></div>`}

async function fetchTaskInternOptions(trackId=''){
  const q=trackId?`?track_id=${encodeURIComponent(trackId)}`:'';
  return await api(`/api/intern-options${q}`);
}
function assignmentStudentRows(rows,selected=new Set()){
  if(!rows.length)return `<div class="empty compact">No interns found for this track.</div>`;
  return rows.map(i=>`<label class="student-pick"><input type="checkbox" class="task-student-check" value="${i.id}" ${selected.has(i.id)?'checked':''}><span><b>${esc(i.full_name)}</b><small>${esc(i.internal_id)} · ${esc(i.email)}</small></span><em>${esc(i.track_name||'Pending Track')}</em></label>`).join('');
}
async function createTask(){
  const initial=await fetchTaskInternOptions();
  state.taskInternOptions=initial;
  const d=modal('Create Task',`<form id="taskForm" class="task-create-form">
    <div class="form-grid">
      <div class="field span2"><label>Title</label><input name="title" required placeholder="e.g. Sales Analysis Project"></div>
      <div class="field span2"><label>Description</label><textarea name="description" rows="3" placeholder="Short task description"></textarea></div>
      <div class="field span2"><label>Instructions</label><textarea name="instructions" rows="3" placeholder="Requirements, checklist, submission notes..."></textarea></div>
      <div class="field"><label>Track Filter</label><select id="taskTrack" name="target_track_id"><option value="">— All Tracks —</option>${tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><div class="small">Choose “—” to show all available interns.</div></div>
      <div class="field"><label>Priority</label><select name="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></div>
      <div class="field"><label>Deadline</label><input name="deadline" type="datetime-local"></div>
      <div class="field"><label>Max Score</label><input name="max_score" type="number" min="1" value="100"></div>
      <div class="field span2 assignment-panel">
        <div class="assignment-head"><div><label>Students</label><div class="small">The list changes instantly with the selected track.</div></div><div class="group"><button type="button" class="btn btn-soft btn-mini" id="selectAllStudents">Select All Shown</button><button type="button" class="btn btn-outline btn-mini" id="clearStudents">Clear</button></div></div>
        <div id="taskStudentList" class="student-picker">${assignmentStudentRows(initial)}</div>
        <div id="assignmentRule" class="assignment-rule"><b>Rule:</b> no students selected + no track = assign to all ${me.role==='admin'?'your assigned ':''}interns.</div>
      </div>
      <div class="field span2"><label>Task Attachments — Any File Type</label><input name="files" type="file" multiple><div class="small">IPYNB, PDF, DOCX, XLSX, ZIP, images, code, datasets and any other file type.</div></div>
    </div>
    <button class="btn btn-primary btn-block">Create & Assign Task</button>
  </form>`);
  const trackEl=d.querySelector('#taskTrack'), listEl=d.querySelector('#taskStudentList'), ruleEl=d.querySelector('#assignmentRule');
  const updateRule=()=>{
    const selected=[...d.querySelectorAll('.task-student-check:checked')].length;
    const trackName=trackEl.options[trackEl.selectedIndex]?.text||'—';
    ruleEl.innerHTML=selected?`<b>Assignment:</b> ${selected} selected student${selected===1?'':'s'} only.`:trackEl.value?`<b>Assignment:</b> all interns in <span>${esc(trackName)}</span>.`:`<b>Assignment:</b> all ${me.role==='admin'?'interns in your mentor scope':'interns'} across all tracks.`;
  };
  const reloadStudents=async()=>{
    listEl.innerHTML='<div class="empty compact">Loading students…</div>';
    const rows=await fetchTaskInternOptions(trackEl.value);
    state.taskInternOptions=rows;
    listEl.innerHTML=assignmentStudentRows(rows);
    d.querySelectorAll('.task-student-check').forEach(x=>x.onchange=updateRule);
    updateRule();
  };
  trackEl.onchange=reloadStudents;
  d.querySelectorAll('.task-student-check').forEach(x=>x.onchange=updateRule);
  d.querySelector('#selectAllStudents').onclick=()=>{d.querySelectorAll('.task-student-check').forEach(x=>x.checked=true);updateRule()};
  d.querySelector('#clearStudents').onclick=()=>{d.querySelectorAll('.task-student-check').forEach(x=>x.checked=false);updateRule()};
  updateRule();
  d.querySelector('#taskForm').onsubmit=async e=>{
    e.preventDefault();
    const fd=new FormData(e.target),files=fd.getAll('files').filter(f=>f&&f.name);
    const selected=[...d.querySelectorAll('.task-student-check:checked')].map(x=>Number(x.value));
    const trackId=trackEl.value?Number(trackEl.value):null;
    const p={
      title:fd.get('title'),description:fd.get('description')||'',instructions:fd.get('instructions')||'',
      target_type:selected.length?'specific':(trackId?'track':'all'),target_track_id:trackId,
      target_user_id:selected.length===1?selected[0]:null,target_user_ids:selected,
      priority:fd.get('priority')||'Medium',deadline:fd.get('deadline')?new Date(fd.get('deadline')).toISOString():null,
      max_score:Number(fd.get('max_score')||100),grace_minutes:0,allow_resubmission:true
    };
    try{
      const r=await api('/api/tasks',{method:'POST',body:p});
      if(files.length){const f2=new FormData();files.forEach(f=>f2.append('uploads',f));await api(`/api/tasks/${r.id}/attachments`,{method:'POST',body:f2})}
      d.remove();toast(`Task created and assigned to ${r.assigned} intern(s)`);go('tasks');
    }catch(ex){err(ex)}
  };
}
function uploadTaskFiles(id){const d=modal('Upload Task Files',`<form><div class="field"><label>Any File Type</label><input name="uploads" type="file" multiple required></div><button class="btn btn-primary">Upload Files</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/tasks/${id}/attachments`,{method:'POST',body:new FormData(e.target)});d.remove();toast('Files uploaded');go('tasks')}catch(ex){err(ex)}}}
function taskDetail(id){const t=state.tasks.find(x=>x.id===id);const assigned=(t.assigned_students||[]).map(x=>esc(x.name)).join(' · ');const d=modal(esc(t.title),`<p>${esc(t.description)}</p>${t.instructions?`<div class="announcement"><b>Instructions</b><p>${esc(t.instructions)}</p></div>`:''}<div class="profile-facts"><div class="fact"><b>Deadline</b>${fmt(t.deadline)}</div><div class="fact"><b>Priority</b>${esc(t.priority)}</div><div class="fact"><b>Max Score</b>${t.max_score}</div><div class="fact"><b>Status</b>${esc(t.progress||'Management')}</div></div>${me.role!=='intern'?`<div class="announcement"><b>Assigned To</b><p>${taskTargetLabel(t)}</p><div class="small">${assigned||'Recipients are stored in Task Assignments.'}</div></div>`:''}<h3>Task Files</h3><div class="files">${t.attachments.map(f=>`<div class="file-row"><span>${esc(f.name)} <small>${fileSize(f.size)}</small></span><a class="btn btn-soft" href="${f.download_url}" target="_blank">Download</a></div>`).join('')||'<div class="small">No files attached.</div>'}</div>${me.role==='intern'?internTaskActions(t):''}`);return d}
function internTaskActions(t){return `<div style="margin-top:20px"><h3>Work & Submission</h3><div class="group"><button class="btn btn-outline" onclick="setTaskStatus(${t.id},'In Progress')">Start / In Progress</button><button class="btn btn-soft" onclick="startWork(${t.id})">Start Work Timer</button><button class="btn btn-outline" onclick="stopWork()">Stop Timer</button><button class="btn btn-primary" onclick="submitTask(${t.id})">Submit Work</button></div>${t.submission?`<div class="announcement" style="margin-top:12px"><b>Latest Submission v${t.submission.version}</b><div>${badge(t.submission.status)} ${t.submission.score!=null?badge(`Score ${t.submission.score}/${t.max_score}`):''}</div><p>${esc(t.submission.feedback||'Awaiting / no feedback yet.')}</p></div>`:''}</div>`}
async function setTaskStatus(id,status){try{await api(`/api/tasks/${id}/status`,{method:'PATCH',body:{status}});toast('Task status updated');document.querySelector('.modal')?.remove();go('tasks')}catch(ex){err(ex)}}
async function startWork(id){try{await api(`/api/work/start/${id}`,{method:'POST'});toast('Work timer started')}catch(ex){err(ex)}}
async function stopWork(){try{const r=await api('/api/work/stop',{method:'POST',body:{}});toast(`Timer stopped · ${r.minutes} min`)}catch(ex){err(ex)}}
function submitTask(id){const d=modal('Submit Task',`<form><div class="field"><label>Upload Files — Any Type</label><input name="uploads" type="file" multiple></div><div class="field"><label>GitHub URL</label><input name="github_url"></div><div class="field"><label>Drive URL</label><input name="drive_url"></div><div class="field"><label>Notes</label><textarea name="notes" rows="4"></textarea></div><button class="btn btn-primary">Submit Task</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/tasks/${id}/submit`,{method:'POST',body:new FormData(e.target)});d.remove();document.querySelectorAll('.modal').forEach(x=>x.remove());toast('Task submitted');go('tasks')}catch(ex){err(ex)}}}

function submissionTable(rows,showReview=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Task</th><th>Version</th><th>Submitted</th><th>Status</th><th>Score</th><th>Files</th><th>Actions</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.student)}</td><td>${esc(s.task?.title)}</td><td>v${s.version}</td><td>${fmt(s.submitted_at)}${s.is_late?` ${badge('Late')}`:''}</td><td>${badge(s.status)}</td><td>${s.score??'—'}</td><td>${s.files.length}</td><td><button class="btn btn-primary" onclick="reviewSubmission(${s.id})">${showReview?'Review':'Open'}</button></td></tr>`).join('')||'<tr><td colspan="8">No submissions.</td></tr>'}</tbody></table></div>`}
async function viewSubmissions(c){const rows=await api('/api/submissions');state.submissions=rows;c.innerHTML=hero('Submission Review Center','Download intern work, review every version, score it and request changes when needed.','REVIEW & QUALITY')+`<div class="card" style="margin-top:15px"><div class="toolbar"><b>${rows.length} Submission Versions</b><span class="small">All uploaded intern files are downloadable by authorized reviewers.</span></div>${submissionTable(rows,true)}</div>`}
function reviewSubmission(id){const s=state.submissions.find(x=>x.id===id);const d=modal(`Review · ${esc(s.task.title)}`,`<div class="announcement"><b>${esc(s.student)}</b><div class="small">${esc(s.student_email)} · Version ${s.version} · ${fmt(s.submitted_at)}</div>${s.is_late?badge('Late'):badge('On Time')}</div><h3>Submitted Files</h3><div class="files">${s.files.map(f=>`<div class="file-row"><span>${esc(f.name)} <small>${fileSize(f.size)}</small></span><a class="btn btn-primary" href="${f.download_url}" target="_blank">Download</a></div>`).join('')||'<div class="small">No file uploaded.</div>'}</div>${s.github_url?`<p><a href="${esc(s.github_url)}" target="_blank">Open GitHub Repository ↗</a></p>`:''}${s.drive_url?`<p><a href="${esc(s.drive_url)}" target="_blank">Open Google Drive ↗</a></p>`:''}<p>${esc(s.notes||'')}</p><form><div class="field"><label>Score / ${s.task.max_score}</label><input name="score" type="number" min="0" max="${s.task.max_score}" value="${s.score??''}"></div><div class="field"><label>Feedback</label><textarea name="feedback" rows="5">${esc(s.feedback||'')}</textarea></div><div class="field"><label>Decision</label><select name="status"><option>Under Review</option><option>Completed</option><option>Changes Requested</option><option>Rejected</option></select></div><button class="btn btn-primary">Save Review</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.score=p.score?Number(p.score):null;try{await api(`/api/submissions/${id}/review`,{method:'POST',body:p});d.remove();toast('Review saved');go('submissions')}catch(ex){err(ex)}}}

async function viewMeetings(c){const rows=await api('/api/meetings');state.meetings=rows;c.innerHTML=hero('Meetings & Attendance',me.role==='super_admin'?'Schedule intern meetings or private operations meetings with Admins / Mentors.':me.role==='admin'?'Schedule meetings with your assigned interns and record attendance.':'Your upcoming and past HVIA meetings.','CALENDAR & FOLLOW-UP')+`${me.role!=='intern'?`<div class="card" style="margin-top:15px"><div class="toolbar"><b>Meeting Scheduler</b><button class="btn btn-primary" onclick="createMeeting()">+ Schedule Meeting</button></div></div>`:''}<div class="grid two"><div class="card"><h3>Meetings</h3>${rows.map(m=>`<div class="meeting"><div class="datebox">${new Date(m.starts_at).toLocaleDateString([],{month:'short',day:'numeric'})}</div><div><b>${esc(m.title)}</b><div class="small">${fmt(m.starts_at)} · ${m.duration_minutes} min · ${m.attendee_count} attendees</div></div><div class="actions">${m.meeting_link?`<a class="btn btn-primary" href="${esc(m.meeting_link)}" target="_blank">Join</a>`:''}${me.role!=='intern'?`<button class="btn btn-outline" onclick="attendance(${m.id})">Attendance</button>`:''}</div></div>`).join('')||'<div class="empty">No meetings.</div>'}</div><div class="card"><h3>Attendance Model</h3><p class="muted">Authorized admins can mark each invited person as Present, Late, Absent or Excused. These records feed performance monitoring and certificate eligibility.</p></div></div>`}
async function createMeeting(){if(!state.interns&&me.role!=='intern')state.interns=await api('/api/interns');const d=modal('Schedule Meeting',`<form><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="form-grid"><div class="field"><label>Date & Time</label><input name="starts_at" type="datetime-local" required></div><div class="field"><label>Duration (minutes)</label><input name="duration_minutes" type="number" value="60"></div><div class="field"><label>Audience</label><select name="target_type"><option value="interns">All ${me.role==='admin'?'Assigned ':''}Interns</option>${me.role==='super_admin'?'<option value="admins">All Admins / Mentors</option><option value="all">Everyone</option>':''}<option value="track">One Track</option><option value="specific">Specific Person</option></select></div><div class="field"><label>Track</label><select name="target_track_id"><option value="">—</option>${tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Specific Intern</label><select name="target_user_id"><option value="">—</option>${(state.interns||[]).map(i=>`<option value="${i.id}">${esc(i.full_name)}</option>`).join('')}</select></div><div class="field"><label>Meeting Link</label><input name="meeting_link"></div></div><button class="btn btn-primary">Schedule & Notify</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.starts_at=new Date(p.starts_at).toISOString();p.duration_minutes=Number(p.duration_minutes);p.target_track_id=p.target_track_id?Number(p.target_track_id):null;p.target_user_id=p.target_user_id?Number(p.target_user_id):null;try{await api('/api/meetings',{method:'POST',body:p});d.remove();toast('Meeting scheduled');go('meetings')}catch(ex){err(ex)}}}
async function attendance(id){const rows=await api(`/api/meetings/${id}/attendance`);const d=modal('Meeting Attendance',rows.map(x=>`<div class="file-row"><span><b>${esc(x.name)}</b><div class="small">${esc(x.role)}</div></span><select class="mini-input" style="width:150px" data-id="${x.id}"><option value="invited" ${x.status==='invited'?'selected':''}>Invited</option><option value="present" ${x.status==='present'?'selected':''}>Present</option><option value="late" ${x.status==='late'?'selected':''}>Late</option><option value="absent" ${x.status==='absent'?'selected':''}>Absent</option><option value="excused" ${x.status==='excused'?'selected':''}>Excused</option></select></div>`).join('')+`<button class="btn btn-primary" style="margin-top:14px" id="saveAttendance">Save Attendance</button>`);d.querySelector('#saveAttendance').onclick=async()=>{try{for(const s of d.querySelectorAll('select[data-id]'))await api(`/api/meetings/attendance/${s.dataset.id}`,{method:'PATCH',body:{status:s.value,note:''}});d.remove();toast('Attendance saved');go('meetings')}catch(ex){err(ex)}}}

async function viewNotes(c){const rows=await api('/api/admin-notes');c.innerHTML=hero(me.role==='super_admin'?'Admin Notes':'Notes from Super Admin',me.role==='super_admin'?'Operational instructions sent directly to Admin / Mentor notifications.':'Important instructions and follow-ups from the Super Admin.','INTERNAL COMMUNICATION')+`<div class="card" style="margin-top:15px">${rows.map(x=>`<div class="announcement"><div class="toolbar"><b>${esc(x.title)}</b>${badge(x.priority)}</div><p>${esc(x.content)}</p><div class="small">${fmt(x.created_at)} · ${x.acknowledged?'Acknowledged':'Pending acknowledgement'}</div>${me.role==='admin'&&!x.acknowledged?`<button class="btn btn-primary" style="margin-top:8px" onclick="ackNote(${x.id})">Acknowledge</button>`:''}</div>`).join('')||'<div class="empty">No admin notes.</div>'}</div>`}
async function ackNote(id){await api(`/api/admin-notes/${id}/ack`,{method:'PATCH'});toast('Acknowledged');go('notes')}

async function viewComplaints(c){const rows=await api('/api/complaints');state.complaints=rows;c.innerHTML=hero('Complaints & Support',me.role==='intern'?'Send a private complaint directly to the HVIA Super Admin. Admin / Mentor accounts cannot access this panel.':'Private intern complaints visible only to the Super Admin.','PRIVATE CHANNEL')+`${me.role==='intern'?`<div class="card" style="margin-top:15px"><button class="btn btn-primary" onclick="newComplaint()">+ New Complaint</button></div>`:''}<div class="card" style="margin-top:15px">${rows.map(x=>`<div class="announcement"><div class="toolbar"><div><b>${esc(x.subject)}</b><div class="small">${me.role==='super_admin'?esc(x.student)+' · ':''}${fmt(x.created_at)}</div></div>${badge(x.status)}</div><p>${esc(x.message)}</p>${x.reply?`<div class="file-row"><span><b>Super Admin Reply</b><br>${esc(x.reply)}</span></div>`:''}${me.role==='super_admin'?`<button class="btn btn-primary" onclick="replyComplaint(${x.id})">Reply / Update</button>`:''}</div>`).join('')||'<div class="empty">No complaints.</div>'}</div>`}
function newComplaint(){const d=modal('New Complaint',`<form><div class="field"><label>Subject</label><input name="subject" required></div><div class="form-grid"><div class="field"><label>Category</label><select name="category"><option>General</option><option>Tasks</option><option>Mentor</option><option>Meetings</option><option>Technical</option><option>Other</option></select></div><div class="field"><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div></div><div class="field"><label>Message</label><textarea name="message" rows="6" required></textarea></div><button class="btn btn-primary">Send to Super Admin</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/complaints',{method:'POST',body:Object.fromEntries(new FormData(e.target))});d.remove();toast('Complaint sent privately');go('complaints')}catch(ex){err(ex)}}}
function replyComplaint(id){const x=state.complaints.find(c=>c.id===id);const d=modal('Reply to Complaint',`<form><div class="field"><label>Status</label><select name="status"><option>In Progress</option><option>Resolved</option><option>Closed</option></select></div><div class="field"><label>Reply</label><textarea name="reply" rows="5">${esc(x.reply||'')}</textarea></div><button class="btn btn-primary">Update Complaint</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/complaints/${id}/reply`,{method:'POST',body:Object.fromEntries(new FormData(e.target))});d.remove();toast('Complaint updated');go('complaints')}catch(ex){err(ex)}}}

async function viewResources(c){const rows=await api('/api/resources');c.innerHTML=hero(me.role==='intern'?'My Learning':'Learning Resources',me.role==='intern'?'Videos, books, files and learning materials for your selected track.':'Upload and organize resources by track.','LEARNING HUB')+`${me.role!=='intern'?`<div class="card" style="margin-top:15px"><button class="btn btn-primary" onclick="uploadResource()">+ Upload Resource</button></div>`:''}<div class="resource-grid" style="margin-top:15px">${rows.map(r=>`<div class="resource"><div class="resource-cover">${r.resource_type==='video'?'▶':r.resource_type==='book'?'BOOK':'FILE'}</div><div class="resource-body">${badge(r.module_name||'Resource')}<h3>${esc(r.title)}</h3><p class="small">${esc(r.description||'')}</p>${me.role==='intern'?`<div class="bar"><i style="width:${r.progress||0}%"></i></div><div class="small" style="margin:6px 0">${r.progress||0}% progress</div>`:''}<a class="btn btn-primary" href="${esc(r.url)}" target="_blank" onclick="resourceOpened(${r.id},${r.resource_type==='video'?25:100})">${r.resource_type==='video'?'Watch':'Open'}</a></div></div>`).join('')||'<div class="empty">No resources.</div>'}</div>`}
function uploadResource(){const d=modal('Upload Learning Resource',`<form><div class="field"><label>Track</label><select name="track_id">${tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Title</label><input name="title" required></div><div class="form-grid"><div class="field"><label>Type</label><select name="resource_type"><option value="video">Video</option><option value="book">Book / PDF</option><option value="file">File</option></select></div><div class="field"><label>Module</label><input name="module_name"></div></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>File</label><input name="upload" type="file" required></div><button class="btn btn-primary">Upload</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/resources/upload',{method:'POST',body:new FormData(e.target)});d.remove();toast('Resource uploaded');go('resources')}catch(ex){err(ex)}}}
async function resourceOpened(id,p){if(me.role!=='intern')return;try{await api(`/api/resources/${id}/progress`,{method:'POST',body:{watched_seconds:0,progress_percent:p,completed:p>=95}})}catch{}}

async function viewAnnouncements(c){const rows=await api('/api/announcements');c.innerHTML=hero('Announcements','Official updates stay inside the system and can be targeted by audience.','COMMUNICATION')+`${me.role!=='intern'?`<div class="card" style="margin-top:15px"><button class="btn btn-primary" onclick="newAnnouncement()">+ Post Announcement</button></div>`:''}<div class="card" style="margin-top:15px">${rows.map(a=>`<div class="announcement">${a.pinned?badge('Pinned'):''}<h3 style="margin-top:9px">${esc(a.title)}</h3><p>${esc(a.content)}</p><div class="small">${fmt(a.created_at)}</div></div>`).join('')}</div>`}
function newAnnouncement(){const d=modal('Post Announcement',`<form><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Content</label><textarea name="content" rows="5" required></textarea></div><div class="form-grid"><div class="field"><label>Audience</label><select name="target_type"><option value="all">All</option><option value="role">Role</option><option value="track">Track</option></select></div><div class="field"><label>Role</label><select name="target_role"><option value="">—</option><option value="intern">Interns</option><option value="admin">Admins</option></select></div><div class="field"><label>Track</label><select name="target_track_id"><option value="">—</option>${tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Publish At (optional)</label><input name="publish_at" type="datetime-local"></div></div><label class="check"><input type="checkbox" name="pinned"> Pin announcement</label><button class="btn btn-primary">Publish</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),p=Object.fromEntries(fd);p.target_track_id=p.target_track_id?Number(p.target_track_id):null;p.pinned=fd.has('pinned');p.publish_at=p.publish_at?new Date(p.publish_at).toISOString():null;try{await api('/api/announcements',{method:'POST',body:p});d.remove();toast('Announcement posted');go('announcements')}catch(ex){err(ex)}}}

async function viewActivity(c){const rows=await api('/api/activity');c.innerHTML=hero('Audit Log','A permanent operational history of logins and major actions inside the HVIA platform.','SYSTEM AUDIT')+`<div class="card" style="margin-top:15px"><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Actor ID</th><th>Action</th><th>Entity</th><th>IP</th><th>Details</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmt(x.created_at)}</td><td>${x.actor_user_id??'System'}</td><td>${esc(x.action)}</td><td>${esc(x.entity_type||'—')} #${x.entity_id??''}</td><td>${esc(x.ip_address||'—')}</td><td>${esc(x.details||'').slice(0,160)}</td></tr>`).join('')}</tbody></table></div></div>`}

async function viewLeads(c){const rows=await api('/api/contact-requests');c.innerHTML=hero('Demo & Business Requests','Requests created from the public HVIA product browser are stored here before continuing on WhatsApp.','BUSINESS INBOX')+`<div class="card" style="margin-top:15px"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Name</th><th>Phone</th><th>Company</th><th>Interest</th><th>Message</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmt(x.created_at)}</td><td><b>${esc(x.name)}</b><div class="small">${esc(x.email||'')}</div></td><td>${esc(x.phone)}</td><td>${esc(x.company||'—')}</td><td>${esc(x.interest||'—')}</td><td>${esc(x.message||'—')}</td></tr>`).join('')}</tbody></table></div></div>`}

async function viewSettings(c){const s=await api('/api/settings');c.innerHTML=hero('System Settings','Control certificate rules, company details and WhatsApp contact from one place.','SYSTEM CONFIGURATION')+`<div class="grid two"><div class="card"><h3>Contact & Company</h3>${settingField('whatsapp_number','WhatsApp Number',s.whatsapp_number)}${settingField('company_name','Company Name',s.company_name)}${settingField('ceo_name','CEO Name',s.ceo_name)}</div><div class="card"><h3>Certificate Eligibility</h3>${settingField('certificate_min_task_percent','Minimum Task Completion %',s.certificate_min_task_percent)}${settingField('certificate_min_attendance_percent','Minimum Attendance %',s.certificate_min_attendance_percent)}</div></div>`}
function settingField(key,label,value){return `<div class="field"><label>${label}</label><div class="group"><input id="set_${key}" value="${esc(value||'')}" style="flex:1"><button class="btn btn-primary" onclick="saveSetting('${key}')">Save</button></div></div>`}
async function saveSetting(k){try{await api(`/api/settings/${k}`,{method:'PATCH',body:{value:document.getElementById(`set_${k}`).value}});toast('Setting saved')}catch(ex){err(ex)}}

async function viewNotifications(c){const rows=await api('/api/notifications');c.innerHTML=hero('Notifications','Task assignments, reviews, meetings, admin notes and system updates.','NOTIFICATION CENTER')+`<div class="card" style="margin-top:15px">${rows.map(x=>`<div class="announcement"><div class="toolbar"><b>${esc(x.title)}</b>${x.is_read?badge('Read'):badge('New')}</div><p>${esc(x.message)}</p><div class="small">${fmt(x.created_at)}</div>${!x.is_read?`<button class="btn btn-soft" onclick="markRead(${x.id},this)">Mark Read</button>`:''}</div>`).join('')||'<div class="empty">No notifications.</div>'}</div>`}

async function viewProfile(c){me=await api('/api/auth/me');c.innerHTML=hero('My Profile','Your HVIA identity, account and enrollment information.','ACCOUNT')+`<div class="card" style="margin-top:15px"><div class="profile-head"><div class="profile-avatar">${me.profile_picture?`<img src="${me.profile_picture}?t=${Date.now()}">`:initials(me.full_name)}</div><div><h1 style="margin:0">${esc(me.full_name)}</h1><p>${esc(me.internal_id)} · ${badge(me.status)}</p><div class="small">${esc(me.email)}</div></div><label class="btn btn-primary">Upload Photo<input id="photoUpload" type="file" accept="image/*" hidden></label></div><div class="profile-facts"><div class="fact"><b>Role</b>${esc(me.role)}</div><div class="fact"><b>Track</b>${esc(me.track?.name||'—')}</div><div class="fact"><b>Phone</b>${esc(me.phone||'—')}</div><div class="fact"><b>Personal Email</b>${esc(me.personal_email||'—')}</div><div class="fact"><b>University</b>${esc(me.university||'—')}</div><div class="fact"><b>Faculty</b>${esc(me.faculty||'—')}</div><div class="fact"><b>LinkedIn</b>${me.linkedin_url?`<a href="${esc(me.linkedin_url)}" target="_blank">Open Profile</a>`:'—'}</div><div class="fact"><b>Last Login</b>${fmt(me.last_login_at)}</div></div></div>`;document.getElementById('photoUpload').onchange=async e=>{if(!e.target.files[0])return;const f=new FormData();f.append('upload',e.target.files[0]);try{await api('/api/profile/photo',{method:'POST',body:f});toast('Profile photo updated');viewProfile(c)}catch(ex){err(ex)}}}

async function globalSearch(q){try{const r=await api(`/api/global-search?q=${encodeURIComponent(q)}`);modal(`Search · ${esc(q)}`,`<h3>People</h3>${r.users.map(x=>`<div class="file-row"><span><b>${esc(x.full_name)}</b><div class="small">${esc(x.internal_id)} · ${esc(x.email)}</div></span>${badge(x.role)}</div>`).join('')||'<div class="small">No matches</div>'}<h3>Tasks</h3>${r.tasks.map(x=>`<div class="file-row"><span>${esc(x.title)}</span></div>`).join('')||'<div class="small">No matches</div>'}<h3>Certificates</h3>${r.certificates.map(x=>`<div class="file-row"><span>${esc(x.certificate_id)}</span></div>`).join('')||'<div class="small">No matches</div>'}`)}catch(ex){err(ex)}}


/* =========================================================
   HVIA CONTROL CENTER · V4 DUAL PORTAL
   Approved dual journey entry: Visitor/Client + Team Portal
   Light/Dark theme persists in DB for authenticated users.
   Reports UI intentionally removed.
   ========================================================= */
let hviaTheme=localStorage.getItem('hvia_theme')||'dark';
function applyTheme(t){hviaTheme=(t==='light'?'light':'dark');document.documentElement.setAttribute('data-theme',hviaTheme);localStorage.setItem('hvia_theme',hviaTheme);document.querySelectorAll('.theme-toggle').forEach(b=>b.textContent=hviaTheme==='dark'?'☀':'☾')}
async function toggleTheme(){applyTheme(hviaTheme==='dark'?'light':'dark');if(me){try{await api('/api/preferences/theme',{method:'PATCH',body:{value:hviaTheme}})}catch{}}}
async function syncThemeFromDb(){if(!me){applyTheme(hviaTheme);return}try{const p=await api('/api/preferences');applyTheme(p.theme||hviaTheme)}catch{applyTheme(hviaTheme)}}
function themeButton(){return `<button class="theme-toggle" onclick="toggleTheme()" title="Switch light / dark mode">${hviaTheme==='dark'?'☀':'☾'}</button>`}

async function boot(){
  applyTheme(hviaTheme);
  try{me=await api('/api/auth/me');tracks=await api('/api/tracks');await syncThemeFromDb();if(me.role==='intern'&&!me.profile_completed)return onboarding();shell();}
  catch{me=null;gateway()}
}

