function shell(){
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="side-logo"><img src="/assets/logo.svg"><div class="role-pill">${me.role.replace('_',' ')}</div></div><div class="nav" id="nav">${navItems().map(([sec,id,label])=>`${sec?`<div class="section">${sec}</div>`:''}<button data-view="${id}"><span class="nav-icon">${icons[id]||'•'}</span>${label}</button>`).join('')}</div><div class="sidebar-foot"><b>HVIA CONTROL CENTER</b><br><span class="neon-ver">DUAL PORTAL · V4</span><br>Learn · Build · Grow · Belong</div></aside><main class="main"><header class="topbar"><div class="top-brand"><span class="pulse-dot"></span><b>HVIA</b><span>CONTROL CENTER</span></div><input class="search" id="globalSearch" placeholder="Search ${me.role==='super_admin'?'interns, tasks, meetings...':'your workspace...'}"><div class="top-actions">${themeButton()}<button class="notify-btn" onclick="openNotifications()">◉<span class="notify-count" id="notifyCount">0</span></button><div class="user-chip"><div class="avatar" id="topAvatar">${me.profile_picture?`<img src="${me.profile_picture}?t=${Date.now()}">`:initials(me.full_name)}</div><div><b>${esc(me.full_name)}</b><div class="small">${me.role.replace('_',' ')}</div></div></div><button class="btn btn-outline" onclick="logout()">Logout</button></div></header><div class="content" id="content"></div></main></div>`;
  document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.view,b));
  if(me.role==='super_admin')document.getElementById('globalSearch').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim())globalSearch(e.target.value.trim())};
  refreshNotifications();go('dashboard',document.querySelector('#nav button[data-view="dashboard"]'));
}

async function viewInterns(c){
  const rows=await api('/api/interns');state.interns=rows;
  c.innerHTML=hero(me.role==='super_admin'?'Intern Management':'My Interns',me.role==='super_admin'?'Manage interns, tracks and monitor ownership from one place.':'Only interns assigned to you by the Super Admin appear here.','PEOPLE & PERFORMANCE')+`<div class="card" style="margin-top:15px"><div class="toolbar"><div class="group"><input class="mini-input" id="internFilter" placeholder="Search name, email or ID"><select class="mini-input" id="trackFilter"><option value="">All Tracks</option>${tracks.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div>${me.role==='super_admin'?'<button class="btn btn-primary" onclick="addIntern()">+ Add Intern</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Intern</th><th>Track</th>${me.role==='super_admin'?'<th>Monitor</th>':''}<th>Status</th><th>Tasks</th><th>Score</th><th>Hours</th><th>Attendance</th><th>Actions</th></tr></thead><tbody id="internRows"></tbody></table></div></div>`;
  renderInternRows(rows);document.getElementById('internFilter').oninput=filterInterns;document.getElementById('trackFilter').onchange=filterInterns;
}
function renderInternRows(rows){const tb=document.getElementById('internRows');if(!tb)return;tb.innerHTML=rows.map(x=>`<tr><td>${esc(x.internal_id)}</td><td><b>${esc(x.full_name)}</b><div class="small">${esc(x.email)}</div></td><td>${esc(x.track?.name||'Pending')}</td>${me.role==='super_admin'?`<td>${x.mentor?`<b>${esc(x.mentor.name)}</b><div class="small">${esc(x.mentor.email)}</div>`:'<span class="muted">Unassigned</span>'}</td>`:''}<td>${badge(x.status)}</td><td>${x.report.tasks.completed}/${x.report.tasks.total}</td><td>${x.report.tasks.avg_score}</td><td>${x.report.hours}</td><td>${x.report.attendance.percent}%</td><td><div class="actions"><button class="btn btn-soft" onclick="internDetail(${x.id})">Profile</button>${me.role==='super_admin'?`<button class="btn btn-outline" onclick="changeTrack(${x.id})">Track</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${me.role==='super_admin'?10:9}">No interns.</td></tr>`}

async function internDetail(id){const r=await api(`/api/interns/${id}/summary`);const p=r.user;const person=state.interns?.find(x=>x.id===id);return modal(esc(p.full_name),`<div class="profile-head"><div class="profile-avatar">${p.profile_picture?`<img src="${p.profile_picture}">`:initials(p.full_name)}</div><div><h2>${esc(p.full_name)}</h2><div class="small">${esc(p.internal_id)} · ${esc(p.email)}</div></div>${badge(p.status)}</div><div class="profile-facts"><div class="fact"><b>Track</b>${esc(p.track?.name||'Pending')}</div>${me.role==='super_admin'?`<div class="fact"><b>Monitor</b>${esc(person?.mentor?.name||'Unassigned')}</div>`:''}<div class="fact"><b>Tasks</b>${r.tasks.completed}/${r.tasks.total}</div><div class="fact"><b>Average Score</b>${r.tasks.avg_score}</div><div class="fact"><b>Work Hours</b>${r.hours}</div><div class="fact"><b>Attendance</b>${r.attendance.percent}%</div><div class="fact"><b>Late Submissions</b>${r.tasks.late}</div><div class="fact"><b>Warnings</b>${r.warnings}</div><div class="fact"><b>Last Login</b>${fmt(p.last_login_at)}</div></div>${me.role!=='intern'?`<div class="group" style="margin-top:18px"><button class="btn btn-outline" onclick="warningModal(${id})">Add Warning</button></div>`:''}`)}

async function viewAdmins(c){
  const rows=await api('/api/admins');state.admins=rows;if(!state.interns)state.interns=await api('/api/interns');
  c.innerHTML=hero('Monitors & Admins','The Super Admin creates monitors, assigns their intern scope, monitors activity and can send operational notes.','ROLE CONTROL')+`<div class="card" style="margin-top:15px"><div class="toolbar"><div><h3 style="margin:0">Monitor Team</h3><div class="small">Each intern has one active monitor. Reassigning an intern moves ownership automatically.</div></div><button class="btn btn-primary" onclick="addAdmin()">+ Add Monitor / Admin</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Monitor</th><th>Last Login</th><th>Assigned Interns</th><th>Tasks</th><th>Reviews</th><th>Meetings</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${esc(a.full_name)}</b><div class="small">${esc(a.email)}</div></td><td>${fmt(a.last_login_at)}</td><td><b>${a.assigned_interns}</b></td><td>${a.tasks_created}</td><td>${a.reviews}</td><td>${a.meetings_created}</td><td><div class="actions"><button class="btn btn-primary" onclick="assignMentor(${a.id})">Assign Interns</button><button class="btn btn-outline" onclick="noteAdmin(${a.id})">Send Note</button><button class="btn btn-danger" onclick="archiveAdmin(${a.id})">Archive</button></div></td></tr>`).join('')}</tbody></table></div></div>`;
}

function assignMentor(id){
  const a=state.admins.find(x=>x.id===id), assigned=new Set(a.assigned_intern_ids||[]);
  const d=modal(`Assign Interns · ${esc(a.full_name)}`,`<div class="mentor-scope-tools"><input id="mentorSearch" class="mini-input" placeholder="Search intern"><select id="mentorTrack" class="mini-input"><option value="">All Tracks</option>${tracks.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div><div class="small" style="margin-bottom:10px">Selecting an intern here makes this person their active monitor. If the intern belonged to another monitor, the system reassigns them automatically.</div><div id="mentorPicker" class="mentor-picker"></div><div class="toolbar" style="margin-top:14px"><span id="mentorCount" class="small"></span><button class="btn btn-primary" id="saveScope">Save Monitor Assignment</button></div>`);
  const render=()=>{const q=(d.querySelector('#mentorSearch').value||'').toLowerCase(),t=d.querySelector('#mentorTrack').value;const list=state.interns.filter(i=>(!q||`${i.full_name} ${i.email} ${i.internal_id}`.toLowerCase().includes(q))&&(!t||i.track?.name===t));d.querySelector('#mentorPicker').innerHTML=list.map(i=>`<label class="file-row mentor-row"><span><b>${esc(i.full_name)}</b><div class="small">${esc(i.track?.name||'Pending')} · ${esc(i.internal_id)}${i.mentor&&i.mentor.id!==id?` · currently ${esc(i.mentor.name)}`:''}</div></span><input type="checkbox" value="${i.id}" ${assigned.has(i.id)?'checked':''}></label>`).join('')||'<div class="empty">No matching interns.</div>';d.querySelectorAll('#mentorPicker input').forEach(x=>x.onchange=()=>{const n=Number(x.value);x.checked?assigned.add(n):assigned.delete(n);d.querySelector('#mentorCount').textContent=`${assigned.size} intern(s) selected`});d.querySelector('#mentorCount').textContent=`${assigned.size} intern(s) selected`};
  d.querySelector('#mentorSearch').oninput=render;d.querySelector('#mentorTrack').onchange=render;render();
  d.querySelector('#saveScope').onclick=async()=>{try{await api(`/api/admins/${id}/assign-interns`,{method:'POST',body:{intern_ids:[...assigned]}});d.remove();state.interns=null;toast('Monitor scope updated');go('admins')}catch(ex){err(ex)}};
}


