function confirmAction(title,message,onConfirm,confirmLabel='Confirm'){
  const d=modal(title,`<p class="confirm-message">${esc(message)}</p><div class="group" style="justify-content:flex-end;margin-top:20px"><button class="btn btn-outline" id="cancelConfirm">Cancel</button><button class="btn btn-danger" id="yesConfirm">${esc(confirmLabel)}</button></div>`);
  d.querySelector('#cancelConfirm').onclick=()=>d.remove();
  d.querySelector('#yesConfirm').onclick=async()=>{const b=d.querySelector('#yesConfirm');b.disabled=true;try{await onConfirm();d.remove()}catch(ex){b.disabled=false;err(ex)}};
  return d;
}
async function logout(){
  confirmAction('Log out','Are you sure you want to log out?',async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}me=null;state={};gateway()},'Log out');
}
