function go(view,el){
  document.querySelectorAll('#nav button').forEach(x=>x.classList.remove('active'));(el||document.querySelector(`#nav button[data-view="${view}"]`))?.classList.add('active');
  const c=document.getElementById('content');c.innerHTML='<div class="card">Loading...</div>';
  const fn={dashboard:viewDashboard,interns:viewInterns,admins:viewAdmins,tasks:viewTasks,submissions:viewSubmissions,meetings:viewMeetings,notes:viewNotes,complaints:viewComplaints,activity:viewActivity,leads:viewLeads,settings:viewSettings,resources:viewResources,announcements:viewAnnouncements,notifications:viewNotifications,profile:viewProfile}[view];
  fn?fn(c).catch(err):c.innerHTML='<div class="card">Unknown view</div>';
}
