function renderInternRows(rows){
  const tb=document.getElementById('internRows');if(!tb)return;
  tb.innerHTML=rows.map(x=>`<tr><td>${esc(x.internal_id)}</td><td><b>${esc(x.full_name)}</b><div class="small">${esc(x.email)}</div></td><td>${esc(x.track?.name||'Pending')}</td>${me.role==='super_admin'?`<td>${x.mentor?`<b>${esc(x.mentor.name)}</b><div class="small">${esc(x.mentor.email)}</div>`:'<span class="muted">Unassigned</span>'}</td>`:''}<td>${badge(x.status)}</td><td>${x.report.tasks.completed}/${x.report.tasks.total}</td><td>${x.report.tasks.avg_score}</td><td>${x.report.hours}</td><td>${x.report.attendance.percent}%</td><td><div class="actions"><button class="btn btn-soft" onclick="internDetail(${x.id})">Profile</button>${me.role==='super_admin'?`<button class="btn btn-outline" onclick="editIntern(${x.id})">Edit</button><button class="btn btn-outline" onclick="changeTrack(${x.id})">Track</button><button class="btn btn-danger" onclick="deleteIntern(${x.id})">Delete</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${me.role==='super_admin'?10:9}">No interns.</td></tr>`;
}
function editIntern(id){
  const p=state.interns.find(x=>x.id===id);if(!p)return;
  const d=modal(`Edit Intern · ${esc(p.full_name)}`,`<form id="editInternForm"><div class="form-grid"><div class="field"><label>Full Name</label><input name="full_name" value="${esc(p.full_name)}" required></div><div class="field"><label>HVIA Login Email</label><input name="email" type="email" value="${esc(p.email)}" required></div><div class="field"><label>New Password (optional)</label><input name="password" type="password" placeholder="Leave blank to keep current"></div><div class="field"><label>Personal Email</label><input name="personal_email" type="email" value="${esc(p.personal_email||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(p.phone||'')}"></div><div class="field"><label>Age</label><input name="age" type="number" value="${p.age??''}"></div><div class="field"><label>LinkedIn</label><input name="linkedin_url" value="${esc(p.linkedin_url||'')}"></div><div class="field"><label>University</label><input name="university" value="${esc(p.university||'')}"></div><div class="field"><label>Faculty</label><input name="faculty" value="${esc(p.faculty||'')}"></div><div class="field"><label>Graduation Year</label><input name="graduation_year" type="number" value="${p.graduation_year??''}"></div><div class="field"><label>Status</label><select name="status">${['onboarding','active','on_hold','completed','dropped','terminated'].map(v=>`<option value="${v}" ${p.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="field"><label>Account</label><select name="active"><option value="true" ${p.active?'selected':''}>Active</option><option value="false" ${!p.active?'selected':''}>Disabled</option></select></div></div><button class="btn btn-primary btn-block">Save Changes</button></form>`);
  d.querySelector('#editInternForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),o=Object.fromEntries(fd);o.active=o.active==='true';o.age=o.age?Number(o.age):null;o.graduation_year=o.graduation_year?Number(o.graduation_year):null;if(!o.password)delete o.password;try{await api(`/api/interns/${id}`,{method:'PATCH',body:o});d.remove();toast('Intern updated');go('interns')}catch(ex){err(ex)}};
}
function deleteIntern(id){const p=state.interns.find(x=>x.id===id);confirmAction('Delete intern',`Delete ${p?.full_name||'this intern'} from active access? Historical activity will be kept for audit.`,async()=>{await api(`/api/interns/${id}`,{method:'DELETE'});toast('Intern removed from active access');go('interns')},'Delete intern')}
function importInternsExcel(){
  const d=modal('Bulk Import Interns',`<div class="announcement"><b>Required columns</b><p>username, password, full_name</p><div class="small">Optional: personal_email, track, phone, age, linkedin_url, university, faculty, graduation_year, status, monitor_email.</div></div><form id="bulkInternForm"><div class="field"><label>Excel File (.xlsx)</label><input name="upload" type="file" accept=".xlsx" required></div><div class="group" style="justify-content:space-between"><a class="btn btn-outline" href="/api/interns/import-template">Download Template</a><button class="btn btn-primary">Validate & Import</button></div></form>`);
  d.querySelector('#bulkInternForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/interns/import-xlsx',{method:'POST',body:new FormData(e.target)});d.remove();toast(`${r.imported} intern(s) imported`);go('interns')}catch(ex){err(ex)}};
}
async function viewAdmins(c){
  const rows=await api('/api/admins');state.admins=rows;if(!state.interns)state.interns=await api('/api/interns');
  c.innerHTML=hero('Monitors & Admins','The Super Admin creates, edits, removes monitors and owns intern distribution.','ROLE CONTROL')+`<div class="card" style="margin-top:15px"><div class="toolbar"><div><h3 style="margin:0">Monitor Team</h3><div class="small">Each intern has one active monitor. Reassignment transfers ownership automatically.</div></div><button class="btn btn-primary" onclick="addAdmin()">+ Add Monitor / Admin</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Monitor</th><th>Last Login</th><th>Assigned Interns</th><th>Tasks</th><th>Reviews</th><th>Meetings</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${esc(a.full_name)}</b><div class="small">${esc(a.email)}</div></td><td>${fmt(a.last_login_at)}</td><td><b>${a.assigned_interns}</b></td><td>${a.tasks_created}</td><td>${a.reviews}</td><td>${a.meetings_created}</td><td><div class="actions"><button class="btn btn-primary" onclick="assignMentor(${a.id})">Assign Interns</button><button class="btn btn-outline" onclick="editAdmin(${a.id})">Edit</button><button class="btn btn-outline" onclick="noteAdmin(${a.id})">Send Note</button><button class="btn btn-danger" onclick="deleteAdmin(${a.id})">Delete</button></div></td></tr>`).join('')}</tbody></table></div></div>`;
}
function editAdmin(id){
  const a=state.admins.find(x=>x.id===id);if(!a)return;
  const d=modal(`Edit Monitor · ${esc(a.full_name)}`,`<form id="editAdminForm"><div class="field"><label>Name</label><input name="full_name" value="${esc(a.full_name)}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(a.email)}" required></div><div class="field"><label>New Password (optional)</label><input name="password" type="password" placeholder="Leave blank to keep current"></div><div class="form-grid"><div class="field"><label>Status</label><select name="status"><option value="active" ${a.status==='active'?'selected':''}>Active</option><option value="on_hold" ${a.status==='on_hold'?'selected':''}>On Hold</option></select></div><div class="field"><label>Account</label><select name="active"><option value="true" ${a.active?'selected':''}>Active</option><option value="false" ${!a.active?'selected':''}>Disabled</option></select></div></div><button class="btn btn-primary btn-block">Save Monitor</button></form>`);
  d.querySelector('#editAdminForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.active=o.active==='true';if(!o.password)delete o.password;try{await api(`/api/admins/${id}`,{method:'PATCH',body:o});d.remove();toast('Monitor updated');go('admins')}catch(ex){err(ex)}};
}
function deleteAdmin(id){const a=state.admins.find(x=>x.id===id);confirmAction('Delete monitor',`Delete ${a?.full_name||'this monitor'}? Assigned interns will become unassigned until the Super Admin redistributes them.`,async()=>{await api(`/api/admins/${id}`,{method:'DELETE'});state.interns=null;toast('Monitor removed');go('admins')},'Delete monitor')}
function taskManagementTable(rows){return `<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Assigned To</th><th>Deadline</th><th>Priority</th><th>Files</th><th>Created</th><th>Actions</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.title)}</b><div class="small">${esc(t.description).slice(0,90)}</div></td><td><b>${taskTargetLabel(t)}</b><div class="small">${(t.assigned_students||[]).slice(0,3).map(x=>esc(x.name)).join(' · ')}${(t.assigned_count||0)>3?' · +'+((t.assigned_count||0)-3):''}</div></td><td>${fmt(t.deadline)}</td><td>${badge(t.priority)}</td><td>${t.attachments.length}</td><td>${dateOnly(t.created_at)}</td><td><div class="actions"><button class="btn btn-soft" onclick="taskDetail(${t.id})">View</button><button class="btn btn-outline" onclick="editTask(${t.id})">Edit</button><button class="btn btn-outline" onclick="uploadTaskFiles(${t.id})">+ Files</button><button class="btn btn-danger" onclick="deleteTask(${t.id})">Delete</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
async function editTask(id){
  const t=state.tasks.find(x=>x.id===id);if(!t)return;
  const initial=await fetchTaskInternOptions(t.target_track_id||'');const selected=new Set(t.target_type==='specific'?(t.assigned_students||[]).map(x=>x.id):[]);
  const local=t.deadline?new Date(t.deadline).toISOString().slice(0,16):'';
  const d=modal(`Edit Task · ${esc(t.title)}`,`<form id="editTaskForm" class="task-create-form"><div class="form-grid"><div class="field span2"><label>Title</label><input name="title" value="${esc(t.title)}" required></div><div class="field span2"><label>Description</label><textarea name="description" rows="3">${esc(t.description||'')}</textarea></div><div class="field span2"><label>Instructions</label><textarea name="instructions" rows="3">${esc(t.instructions||'')}</textarea></div><div class="field"><label>Track Filter</label><select id="editTaskTrack"><option value="">— All Tracks —</option>${tracks.map(x=>`<option value="${x.id}" ${Number(t.target_track_id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select name="priority">${['Low','Medium','High'].map(v=>`<option ${t.priority===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Deadline</label><input name="deadline" type="datetime-local" value="${local}"></div><div class="field"><label>Max Score</label><input name="max_score" type="number" min="1" value="${t.max_score}"></div><div class="field span2 assignment-panel"><div class="assignment-head"><div><label>Students</label><div class="small">Selecting a track filters this list instantly. Leave students empty to target the whole selected track.</div></div><button type="button" class="btn btn-outline btn-mini" id="clearEditStudents">Clear</button></div><div id="editTaskStudentList" class="student-picker">${assignmentStudentRows(initial,selected)}</div></div><div class="field span2"><label>Add New Attachments (optional)</label><input name="files" type="file" multiple></div></div><button class="btn btn-primary btn-block">Save Task Changes</button></form>`);
  const trackEl=d.querySelector('#editTaskTrack'),list=d.querySelector('#editTaskStudentList');
  const reload=async()=>{const rows=await fetchTaskInternOptions(trackEl.value);selected.clear();list.innerHTML=assignmentStudentRows(rows,selected)};trackEl.onchange=reload;d.querySelector('#clearEditStudents').onclick=()=>d.querySelectorAll('#editTaskStudentList input').forEach(x=>x.checked=false);
  d.querySelector('#editTaskForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),files=fd.getAll('files').filter(f=>f&&f.name),ids=[...d.querySelectorAll('#editTaskStudentList input:checked')].map(x=>Number(x.value)),trackId=trackEl.value?Number(trackEl.value):null;const payload={title:fd.get('title'),description:fd.get('description')||'',instructions:fd.get('instructions')||'',target_type:ids.length?'specific':(trackId?'track':'all'),target_track_id:trackId,target_user_id:ids.length===1?ids[0]:null,target_user_ids:ids,priority:fd.get('priority'),deadline:fd.get('deadline')?new Date(fd.get('deadline')).toISOString():null,max_score:Number(fd.get('max_score')||100),grace_minutes:0,allow_resubmission:true};try{const r=await api(`/api/tasks/${id}`,{method:'PATCH',body:payload});if(files.length){const f=new FormData();files.forEach(x=>f.append('uploads',x));await api(`/api/tasks/${id}/attachments`,{method:'POST',body:f})}d.remove();toast(r.retained_with_submission?.length?'Task updated; submitted interns were retained':'Task updated');go('tasks')}catch(ex){err(ex)}};
}
function deleteTask(id){const t=state.tasks.find(x=>x.id===id);confirmAction('Delete task',`Delete “${t?.title||'this task'}”? Existing submissions remain in the audit history, but the task will disappear from active workspaces.`,async()=>{await api(`/api/tasks/${id}`,{method:'DELETE'});toast('Task archived');go('tasks')},'Delete task')}
function toLocalInput(x){if(!x)return'';const d=new Date(x),off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,16)}
async function viewMeetings(c){
  const rows=await api('/api/meetings');state.meetings=rows;
  c.innerHTML=hero('Meetings & Attendance',me.role==='super_admin'?'Meet with interns, one track, a specific intern, all mentors or a specific mentor.':me.role==='admin'?'Schedule meetings only with interns inside your assigned monitor scope.':'Your upcoming and past HVIA meetings.','CALENDAR & FOLLOW-UP')+`${me.role!=='intern'?`<div class="card" style="margin-top:15px"><div class="toolbar"><b>Meeting Scheduler</b><button class="btn btn-primary" onclick="createMeeting()">+ Schedule Meeting</button></div></div>`:''}<div class="grid two"><div class="card"><h3>Meetings</h3>${rows.map(m=>`<div class="meeting"><div class="datebox">${new Date(m.starts_at).toLocaleDateString([],{month:'short',day:'numeric'})}</div><div><b>${esc(m.title)}</b><div class="small">${fmt(m.starts_at)} · ${m.duration_minutes} min · ${m.attendee_count} attendees</div></div><div class="actions">${m.meeting_link?`<a class="btn btn-primary" href="${esc(m.meeting_link)}" target="_blank">Join</a>`:''}${me.role!=='intern'?`<button class="btn btn-outline" onclick="attendance(${m.id})">Attendance</button><button class="btn btn-outline" onclick="editMeeting(${m.id})">Edit</button><button class="btn btn-danger" onclick="deleteMeeting(${m.id})">Delete</button>`:''}</div></div>`).join('')||'<div class="empty">No meetings.</div>'}</div><div class="card"><h3>Audience Rules</h3><p class="muted">One Track requires a track. Specific Intern requires a track first, then the student list is filtered to that track. Only the Super Admin can target mentors/admins.</p></div></div>`;
}
async function createMeeting(existing=null){
  if(me.role==='super_admin'&&!state.adminOptions)state.adminOptions=await api('/api/admin-options');
  const currentType=existing?.target_type||'interns',currentTrack=existing?.target_track_id||'',currentUser=existing?.target_user_id||'';
  let internRows=currentTrack?await fetchTaskInternOptions(currentTrack):[];
  const d=modal(existing?'Edit Meeting':'Schedule Meeting',`<form id="meetingForm"><div class="field"><label>Title</label><input name="title" value="${esc(existing?.title||'')}" required></div><div class="field"><label>Description</label><textarea name="description">${esc(existing?.description||'')}</textarea></div><div class="form-grid"><div class="field"><label>Date & Time</label><input name="starts_at" type="datetime-local" value="${toLocalInput(existing?.starts_at)}" required></div><div class="field"><label>Duration (minutes)</label><input name="duration_minutes" type="number" min="5" value="${existing?.duration_minutes||60}" required></div><div class="field"><label>Audience</label><select id="meetingAudience" name="target_type"><option value="interns" ${currentType==='interns'?'selected':''}>All ${me.role==='admin'?'Assigned ':''}Interns</option><option value="track" ${currentType==='track'?'selected':''}>One Track</option><option value="specific" ${currentType==='specific'?'selected':''}>Specific Intern</option>${me.role==='super_admin'?`<option value="admins" ${currentType==='admins'?'selected':''}>All Mentors / Admins</option><option value="specific_admin" ${currentType==='specific_admin'?'selected':''}>Specific Mentor / Admin</option><option value="all" ${currentType==='all'?'selected':''}>Everyone</option>`:''}</select></div><div class="field" id="meetingTrackField"><label>Track</label><select id="meetingTrack" name="target_track_id"><option value="">Select Track</option>${tracks.map(t=>`<option value="${t.id}" ${Number(currentTrack)===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="field" id="meetingInternField"><label>Specific Intern</label><select id="meetingIntern" name="target_user_id"><option value="">${currentTrack?'Select Intern':'Select a track first'}</option>${internRows.map(i=>`<option value="${i.id}" ${Number(currentUser)===i.id?'selected':''}>${esc(i.full_name)} · ${esc(i.internal_id)}</option>`).join('')}</select></div>${me.role==='super_admin'?`<div class="field" id="meetingAdminField"><label>Specific Mentor / Admin</label><select id="meetingAdmin"><option value="">Select Mentor</option>${(state.adminOptions||[]).map(a=>`<option value="${a.id}" ${Number(currentUser)===a.id?'selected':''}>${esc(a.full_name)} · ${esc(a.email)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Meeting Link</label><input name="meeting_link" value="${esc(existing?.meeting_link||'')}"></div></div><button class="btn btn-primary">${existing?'Save Meeting':'Schedule & Notify'}</button></form>`);
  const audience=d.querySelector('#meetingAudience'),track=d.querySelector('#meetingTrack'),intern=d.querySelector('#meetingIntern'),trackField=d.querySelector('#meetingTrackField'),internField=d.querySelector('#meetingInternField'),adminField=d.querySelector('#meetingAdminField'),adminSel=d.querySelector('#meetingAdmin');
  const refreshFields=()=>{const v=audience.value;const needTrack=v==='track'||v==='specific';trackField.style.display=needTrack?'block':'none';internField.style.display=v==='specific'?'block':'none';if(adminField)adminField.style.display=v==='specific_admin'?'block':'none';track.required=needTrack;intern.required=v==='specific';if(adminSel)adminSel.required=v==='specific_admin'};
  const refreshInterns=async()=>{intern.innerHTML='<option value="">Loading…</option>';if(!track.value){intern.innerHTML='<option value="">Select a track first</option>';return}const rows=await fetchTaskInternOptions(track.value);intern.innerHTML='<option value="">Select Intern</option>'+rows.map(i=>`<option value="${i.id}">${esc(i.full_name)} · ${esc(i.internal_id)}</option>`).join('')};
  audience.onchange=refreshFields;track.onchange=refreshInterns;refreshFields();
  d.querySelector('#meetingForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),tt=audience.value,trackId=(tt==='track'||tt==='specific')?Number(track.value):null;let userId=null;if(tt==='specific')userId=Number(intern.value);if(tt==='specific_admin')userId=Number(adminSel.value);if((tt==='track'||tt==='specific')&&!trackId)return toast('Please choose a track');if(tt==='specific'&&!userId)return toast('Please choose an intern from the selected track');if(tt==='specific_admin'&&!userId)return toast('Please choose a mentor / admin');const p={title:fd.get('title'),description:fd.get('description')||'',starts_at:new Date(fd.get('starts_at')).toISOString(),duration_minutes:Number(fd.get('duration_minutes')||60),meeting_link:fd.get('meeting_link')||'',target_type:tt,target_track_id:trackId,target_user_id:userId};try{await api(existing?`/api/meetings/${existing.id}`:'/api/meetings',{method:existing?'PATCH':'POST',body:p});d.remove();toast(existing?'Meeting updated':'Meeting scheduled');go('meetings')}catch(ex){err(ex)}};
}
function editMeeting(id){const m=state.meetings.find(x=>x.id===id);if(m)createMeeting(m)}
function deleteMeeting(id){const m=state.meetings.find(x=>x.id===id);confirmAction('Delete meeting',`Delete “${m?.title||'this meeting'}”? Attendees will be notified that it was cancelled.`,async()=>{await api(`/api/meetings/${id}`,{method:'DELETE'});toast('Meeting deleted');go('meetings')},'Delete meeting')}
async function viewSettings(c){const s=await api('/api/settings');c.innerHTML=hero('System Settings','Control company information and public contact settings.','SYSTEM CONFIGURATION')+`<div class="grid two"><div class="card"><h3>Contact & Company</h3>${settingField('whatsapp_number','WhatsApp Number',s.whatsapp_number)}${settingField('company_name','Company Name',s.company_name)}${settingField('ceo_name','CEO Name',s.ceo_name)}</div><div class="card"><h3>Platform Rules</h3><p class="muted">Intern assignment ownership is controlled by the Super Admin. Task edits, meeting changes, bulk imports and account changes are recorded in the Audit Log.</p></div></div>`}
async function globalSearch(q){try{const r=await api(`/api/global-search?q=${encodeURIComponent(q)}`);modal(`Search · ${esc(q)}`,`<h3>People</h3>${r.users.map(x=>`<div class="file-row"><span><b>${esc(x.full_name)}</b><div class="small">${esc(x.internal_id)} · ${esc(x.email)}</div></span>${badge(x.role)}</div>`).join('')||'<div class="small">No matches</div>'}<h3>Tasks</h3>${r.tasks.map(x=>`<div class="file-row"><span>${esc(x.title)}</span></div>`).join('')||'<div class="small">No matches</div>'}`)}catch(ex){err(ex)}}


